<section class="panel"><h2>Borrow an item</h2><p>Borrowing immediately reserves stock under your account.</p><?php startForm('borrow'); ?><div class="form-grid"><?php selectField('item_id','Available item',query("SELECT id,CONCAT(name,' — ',quantity,' ',unit,' available') name FROM items WHERE quantity>0 ORDER BY name")->fetchAll()); field('quantity','Quantity',1,'number'); field('due_date','Return due date',date('Y-m-d'),'date'); ?></div><?php endForm('Confirm borrowing'); ?></section>
<section class="panel"><h2>Borrowing history</h2><div class="table-wrap"><table><tr><th>Item / borrower</th><th>Quantity</th><th>Borrowed</th><th>Due</th><th>Returned</th><th>Status</th><th></th></tr><?php $rows=query('SELECT b.*,i.name item,u.name borrower FROM borrowings b JOIN items i ON i.id=b.item_id JOIN users u ON u.id=b.user_id'.(!manager()?' WHERE b.user_id=?':'').' ORDER BY b.id DESC',!manager()?[$me['id']]:[])->fetchAll(); foreach($rows as $r): ?><tr><td><b><?= e($r['item']) ?></b><small><?= e($r['borrower']) ?></small></td><td><?= e($r['quantity']) ?></td><td><?= e($r['borrowed_at']) ?></td><td><?= e($r['due_date']) ?></td><td><?= e($r['returned_at']??'—') ?></td><td><span class="badge <?= $r['status']==='borrowed'?'warn':'' ?>"><?= e($r['status']) ?></span></td><td><?php if($r['status']==='borrowed') { startForm('return',$r['id']); endForm('Return'); } ?></td></tr><?php endforeach ?></table></div><?php if(!$rows) echo '<p class="empty">No borrowing records yet.</p>'; ?></section>
